#include <iostream>
#include <string>

void uppercase_ascii(std::string& text) {
    for (char& ch : text) {
        if (ch >= 'a' && ch <= 'z') ch = static_cast<char>(ch - 'a' + 'A');
    }
}
int main() {
    std::string text;
    std::getline(std::cin, text);
    uppercase_ascii(text);
    std::cout << text << '\n';
}
